def grep(pattern, flags, files):
    flag_set = set(flags.split())
    numbered = "-n" in flag_set
    files_only = "-l" in flag_set
    insensitive = "-i" in flag_set
    invert = "-v" in flag_set
    exact = "-x" in flag_set
    multi = len(files) > 1
    output = []

    for filename in files:
        with open(filename) as file:
            for line_number, raw_line in enumerate(file, start=1):
                line = raw_line.rstrip("\n")
                haystack, needle = line, pattern
                if insensitive:
                    haystack, needle = haystack.lower(), needle.lower()

                matches = haystack == needle if exact else needle in haystack
                if invert:
                    matches = not matches
                if not matches:
                    continue

                if files_only:
                    output.append(f"{filename}\n")
                    break

                prefix = []
                if multi:
                    prefix.append(filename)
                if numbered:
                    prefix.append(str(line_number))

                if prefix:
                    output.append(f"{':'.join(prefix)}:{line}\n")
                else:
                    output.append(f"{line}\n")

    return "".join(output)

